I'll provide you with a comprehensive example of creating a custom REST service in Dynamics AX using X++. This example will demonstrate CRUD operations for a Customer entity.

## 1. Service Contract Interface

```xpp
[
    AifCollectionTypeAttribute('_customers', Types::Class, classStr(CustomCustomerContract)),
    SysEntryPointAttribute(true)
]
class CustomCustomerServiceContract
{
}

/// <summary>
/// Gets all customers
/// </summary>
/// <returns>List of customers</returns>
[
    AifDocumentAttribute(classStr(CustomCustomerContract)),
    SysEntryPointAttribute(true)
]
public List getCustomers()
{
    List customerList = new List(Types::Class);
    CustomCustomer customCustomer = new CustomCustomer();

    return customCustomer.getAllCustomers();
}

/// <summary>
/// Gets a specific customer by account number
/// </summary>
/// <param name="_accountNum">Customer account number</param>
/// <returns>Customer contract</returns>
[
    AifDocumentAttribute(classStr(CustomCustomerContract)),
    SysEntryPointAttribute(true)
]
public CustomCustomerContract getCustomer(str _accountNum)
{
    CustomCustomer customCustomer = new CustomCustomer();

    return customCustomer.getCustomer(_accountNum);
}

/// <summary>
/// Creates a new customer
/// </summary>
/// <param name="_customerContract">Customer data contract</param>
/// <returns>Created customer contract</returns>
[
    AifDocumentAttribute(classStr(CustomCustomerContract)),
    SysEntryPointAttribute(true)
]
public CustomCustomerContract createCustomer(CustomCustomerContract _customerContract)
{
    CustomCustomer customCustomer = new CustomCustomer();

    return customCustomer.createCustomer(_customerContract);
}

/// <summary>
/// Updates an existing customer
/// </summary>
/// <param name="_customerContract">Customer data contract</param>
/// <returns>Updated customer contract</returns>
[
    AifDocumentAttribute(classStr(CustomCustomerContract)),
    SysEntryPointAttribute(true)
]
public CustomCustomerContract updateCustomer(CustomCustomerContract _customerContract)
{
    CustomCustomer customCustomer = new CustomCustomer();

    return customCustomer.updateCustomer(_customerContract);
}

/// <summary>
/// Deletes a customer
/// </summary>
/// <param name="_accountNum">Customer account number</param>
/// <returns>Success status</returns>
[
    SysEntryPointAttribute(true)
]
public boolean deleteCustomer(str _accountNum)
{
    CustomCustomer customCustomer = new CustomCustomer();

    return customCustomer.deleteCustomer(_accountNum);
}
```

## 2. Data Contract Class

```xpp
[
    DataContractAttribute,
    AifQueryTypeAttribute('_customers', queryStr(CustomCustomerQuery))
]
class CustomCustomerContract
{
    AccountNum          accountNum;
    CustName           name;
    DirPartyName       partyName;
    CustGroupId        custGroup;
    LogisticsAddressing address;
    Phone              phone;
    Email              email;
    CurrencyCode       currency;

    [
        DataMemberAttribute('AccountNum'),
        AifQueryFieldAttribute(fieldStr(CustTable, AccountNum))
    ]
    public AccountNum parmAccountNum(AccountNum _accountNum = accountNum)
    {
        accountNum = _accountNum;
        return accountNum;
    }

    [
        DataMemberAttribute('Name'),
        AifQueryFieldAttribute(fieldStr(DirPartyTable, Name))
    ]
    public CustName parmName(CustName _name = name)
    {
        name = _name;
        return name;
    }

    [
        DataMemberAttribute('PartyName'),
        AifQueryFieldAttribute(fieldStr(DirPartyTable, Name))
    ]
    public DirPartyName parmPartyName(DirPartyName _partyName = partyName)
    {
        partyName = _partyName;
        return partyName;
    }

    [
        DataMemberAttribute('CustGroup'),
        AifQueryFieldAttribute(fieldStr(CustTable, CustGroup))
    ]
    public CustGroupId parmCustGroup(CustGroupId _custGroup = custGroup)
    {
        custGroup = _custGroup;
        return custGroup;
    }

    [
        DataMemberAttribute('Phone')
    ]
    public Phone parmPhone(Phone _phone = phone)
    {
        phone = _phone;
        return phone;
    }

    [
        DataMemberAttribute('Email')
    ]
    public Email parmEmail(Email _email = email)
    {
        email = _email;
        return email;
    }

    [
        DataMemberAttribute('Currency'),
        AifQueryFieldAttribute(fieldStr(CustTable, Currency))
    ]
    public CurrencyCode parmCurrency(CurrencyCode _currency = currency)
    {
        currency = _currency;
        return currency;
    }
}
```

## 3. Business Logic Class

```xpp
class CustomCustomer
{
    /// <summary>
    /// Gets all customers
    /// </summary>
    /// <returns>List of customer contracts</returns>
    public List getAllCustomers()
    {
        List                    customerList = new List(Types::Class);
        CustTable              custTable;
        DirPartyTable          partyTable;
        CustomCustomerContract customerContract;

        while select custTable
            join partyTable
            where partyTable.RecId == custTable.Party
        {
            customerContract = this.mapTableToContract(custTable, partyTable);
            customerList.addEnd(customerContract);
        }

        return customerList;
    }

    /// <summary>
    /// Gets a specific customer
    /// </summary>
    /// <param name="_accountNum">Customer account number</param>
    /// <returns>Customer contract</returns>
    public CustomCustomerContract getCustomer(str _accountNum)
    {
        CustTable              custTable;
        DirPartyTable          partyTable;
        CustomCustomerContract customerContract;

        select firstonly custTable
            join partyTable
            where custTable.AccountNum == _accountNum
                && partyTable.RecId == custTable.Party;

        if (custTable)
        {
            customerContract = this.mapTableToContract(custTable, partyTable);
        }
        else
        {
            throw error(strFmt("Customer %1 not found", _accountNum));
        }

        return customerContract;
    }

    /// <summary>
    /// Creates a new customer
    /// </summary>
    /// <param name="_customerContract">Customer contract</param>
    /// <returns>Created customer contract</returns>
    public CustomCustomerContract createCustomer(CustomCustomerContract _customerContract)
    {
        CustTable              custTable;
        DirPartyTable          partyTable;
        NumberSeq              numberSeq;
        CustomCustomerContract returnContract;

        ttsbegin;

        try
        {
            // Create party
            partyTable.clear();
            partyTable.PartyType = DirPartyType::Organization;
            partyTable.Name = _customerContract.parmPartyName();
            partyTable.insert();

            // Create customer
            custTable.clear();

            // Auto-generate account number if not provided
            if (!_customerContract.parmAccountNum())
            {
                numberSeq = NumberSeq::newGetNum(CustParameters::numRefCustAccount());
                custTable.AccountNum = numberSeq.num();
            }
            else
            {
                custTable.AccountNum = _customerContract.parmAccountNum();
            }

            custTable.Party = partyTable.RecId;
            custTable.CustGroup = _customerContract.parmCustGroup() ? _customerContract.parmCustGroup() : CustParameters::find().CustGroup;
            custTable.Currency = _customerContract.parmCurrency() ? _customerContract.parmCurrency() : CompanyInfo::standardCurrency();

            custTable.insert();

            // Create contact information if provided
            if (_customerContract.parmPhone())
            {
                this.createContactInfo(custTable.Party, LogisticsElectronicAddressMethodType::Phone, _customerContract.parmPhone());
            }

            if (_customerContract.parmEmail())
            {
                this.createContactInfo(custTable.Party, LogisticsElectronicAddressMethodType::Email, _customerContract.parmEmail());
            }

            ttscommit;

            // Return the created customer
            returnContract = this.getCustomer(custTable.AccountNum);
        }
        catch (Exception::Error)
        {
            ttsabort;
            throw error("Failed to create customer");
        }

        return returnContract;
    }

    /// <summary>
    /// Updates an existing customer
    /// </summary>
    /// <param name="_customerContract">Customer contract</param>
    /// <returns>Updated customer contract</returns>
    public CustomCustomerContract updateCustomer(CustomCustomerContract _customerContract)
    {
        CustTable              custTable;
        DirPartyTable          partyTable;
        CustomCustomerContract returnContract;

        ttsbegin;

        try
        {
            select forupdate custTable
                join forupdate partyTable
                where custTable.AccountNum == _customerContract.parmAccountNum()
                    && partyTable.RecId == custTable.Party;

            if (!custTable)
            {
                throw error(strFmt("Customer %1 not found", _customerContract.parmAccountNum()));
            }

            // Update party information
            if (_customerContract.parmPartyName())
            {
                partyTable.Name = _customerContract.parmPartyName();
                partyTable.update();
            }

            // Update customer information
            if (_customerContract.parmCustGroup())
            {
                custTable.CustGroup = _customerContract.parmCustGroup();
            }

            if (_customerContract.parmCurrency())
            {
                custTable.Currency = _customerContract.parmCurrency();
            }

            custTable.update();

            ttscommit;

            // Return the updated customer
            returnContract = this.getCustomer(custTable.AccountNum);
        }
        catch (Exception::Error)
        {
            ttsabort;
            throw error("Failed to update customer");
        }

        return returnContract;
    }

    /// <summary>
    /// Deletes a customer
    /// </summary>
    /// <param name="_accountNum">Customer account number</param>
    /// <returns>Success status</returns>
    public boolean deleteCustomer(str _accountNum)
    {
        CustTable custTable;
        boolean success = false;

        ttsbegin;

        try
        {
            select forupdate custTable
                where custTable.AccountNum == _accountNum;

            if (!custTable)
            {
                throw error(strFmt("Customer %1 not found", _accountNum));
            }

            custTable.delete();

            ttscommit;
            success = true;
        }
        catch (Exception::Error)
        {
            ttsabort;
            throw error("Failed to delete customer");
        }

        return success;
    }

    /// <summary>
    /// Maps table data to contract
    /// </summary>
    /// <param name="_custTable">Customer table</param>
    /// <param name="_partyTable">Party table</param>
    /// <returns>Customer contract</returns>
    private CustomCustomerContract mapTableToContract(CustTable _custTable, DirPartyTable _partyTable)
    {
        CustomCustomerContract customerContract = new CustomCustomerContract();
        LogisticsElectronicAddress electronicAddress;

        customerContract.parmAccountNum(_custTable.AccountNum);
        customerContract.parmName(_custTable.name());
        customerContract.parmPartyName(_partyTable.Name);
        customerContract.parmCustGroup(_custTable.CustGroup);
        customerContract.parmCurrency(_custTable.Currency);

        // Get phone number
        select firstonly electronicAddress
            where electronicAddress.Party == _custTable.Party
                && electronicAddress.Type == LogisticsElectronicAddressMethodType::Phone;

        if (electronicAddress)
        {
            customerContract.parmPhone(electronicAddress.Locator);
        }

        // Get email
        select firstonly electronicAddress
            where electronicAddress.Party == _custTable.Party
                && electronicAddress.Type == LogisticsElectronicAddressMethodType::Email;

        if (electronicAddress)
        {
            customerContract.parmEmail(electronicAddress.Locator);
        }

        return customerContract;
    }

    /// <summary>
    /// Creates contact information
    /// </summary>
    /// <param name="_partyRecId">Party record ID</param>
    /// <param name="_type">Address type</param>
    /// <param name="_locator">Contact information</param>
    private void createContactInfo(RefRecId _partyRecId, LogisticsElectronicAddressMethodType _type, str _locator)
    {
        LogisticsElectronicAddress electronicAddress;

        electronicAddress.clear();
        electronicAddress.Party = _partyRecId;
        electronicAddress.Type = _type;
        electronicAddress.Locator = _locator;
        electronicAddress.IsPrimary = NoYes::Yes;
        electronicAddress.insert();
    }
}
```

## 4. Service Group Configuration

After creating the classes, you need to:

1. **Create a Service Group** in AOT:
   - Navigate to `Services > Service Groups`
   - Create a new Service Group named `CustomCustomerServiceGroup`
   - Add the `CustomCustomerServiceContract` class as a service

2. **Deploy the Service**:
   - Right-click on the Service Group
   - Select "Deploy Service Group"

3. **Configure IIS** (if needed):
   - The service will be automatically deployed to IIS
   - The WSDL will be available at: `http://yourserver:8101/DynamicsAx/Services/CustomCustomerServiceGroup`

## 5. Usage Examples

### REST API Endpoints:
- **GET** `/DynamicsAx/Services/CustomCustomerServiceGroup/getCustomers` - Get all customers
- **GET** `/DynamicsAx/Services/CustomCustomerServiceGroup/getCustomer` - Get specific customer
- **POST** `/DynamicsAx/Services/CustomCustomerServiceGroup/createCustomer` - Create customer
- **PUT** `/DynamicsAx/Services/CustomCustomerServiceGroup/updateCustomer` - Update customer
- **DELETE** `/DynamicsAx/Services/CustomCustomerServiceGroup/deleteCustomer` - Delete customer

### Sample JSON Request (Create Customer):
```json
{
    "partyName": "Test Customer Ltd",
    "custGroup": "10",
    "phone": "+1-555-0123",
    "email": "test@customer.com",
    "currency": "USD"
}
```

This REST service provides a complete CRUD interface for customer management in Dynamics AX with proper error handling, transaction management, and data contracts.

